<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Order Request</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            padding: 20px;
            background-color: #f5f5f5;
        }
        .container {
            background: #fff;
            padding: 20px;
            border-radius: 8px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.1);
        }
        h2 {
            margin-bottom: 20px;
        }
        form {
            display: flex;
            flex-direction: column;
        }
        input, select {
            padding: 10px;
            margin-bottom: 10px;
            border: 1px solid #ccc;
            border-radius: 4px;
        }
        button {
            background-color: #007BFF;
            color: white;
            padding: 10px 15px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background-color: #0056b3;
        }
        .status {
            margin-top: 20px;
            font-weight: bold;
            color: #28a745;
        }
    </style>
</head>
<body>
    <div class="container">
        <h2>Make Payment Request</h2>
        <form id="paymentForm">
            <input type="text" id="cardNumber" placeholder="Credit Card Number" required>
            <input type="text" id="expiryDate" placeholder="Expiry Date" required>
            <input type="text" id="cvv" placeholder="CVV" required>
            <input type="text" id="amount" placeholder="Amount" required>
            <button type="submit">Submit Payment</button>
        </form>
        <div class="status" id="statusMessage"></div>
    </div>

    <script>
        document.getElementById('paymentForm').addEventListener('submit', function(event) {
            event.preventDefault();
            const cardNumber = document.getElementById('cardNumber').value;
            const expiryDate = document.getElementById('expiryDate').value;
            const cvv = document.getElementById('cvv').value;
            const amount = document.getElementById('amount').value;
            const statusMessage = document.getElementById('statusMessage');

            // Validate input
            if (!cardNumber || !expiryDate || !cvv || !amount) {
                statusMessage.textContent = "Please fill in all fields.";
                return;
            }

            // Calculate 10% as a discount
            const discountedAmount = amount * 0.9;

            // Show payment success message
            statusMessage.textContent = "Payment successful with 10% discount!";
        });
    </script>
</body>
</html>

