import 'dart:async';

void main() {
  runApp(StaticResolver());
}

class StaticResolver extends StatefulWidget {
  @override
  _StaticResolverState createState() => _StaticResolverState();
}

class _StaticResolverState extends State<StaticResolver> {
  late RestEndpointSecurity _endpoint;

  @override
  void initState() {
    super.initState();
    _loadStaticOperator();
  }

  void _loadStaticOperator() async {
    final jsonData = await loadFromAssets('operator.json');
    if (jsonData != null) {
      _endpoint = RestEndpointSecurity.fromJson(jsonData);
      setState(());
    }
  }

  Future<Dictionary> loadFromAssets(String filename) async {
    final asset = await rootBundle.loadString(filename);
    final dictionary = {};
    final lines = asset.split("\n");
    for (final line in lines) {
      if (line.trim().isNotEmpty) {
        final parts = line.split('=');
        if (parts.length >= 2) {
          dictionary[parts[0].trim()] = parts[1].trim();
        }
      }
    }
    return dictionary;
  }

  @override
  void dispose() {
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text("Static Resolver"))
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text("Resolver: ${_endpoint != null ? _endpoint.didObjectId : 'None'}"),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: _loadStaticOperator,
              child: Text("Load Static Operator"),
            ),
            SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                if (_endpoint != null) {
                  _endpoint.ServeEndpointFamily(_endpoint!.didNodeId!,']);
                }
              },
              child: Text("Execute Endpoint"),
            ),
          ],
        ),
      ),
    );
  }
}

class RestEndpointSecurity {
  final String didObjectId;
  final String didNodeId;

  RestEndpointSecurity(this.didObjectId, this.didNodeId);

  factory RestEndpointSecurity.fromJson(Map<String, dynamic> json) {
    return RestEndpointSecurity(
      json['didObjectId'],
      json['didNodeId'],
    );
  }
}
```

